  Forecast_t101 = {
    id = "Forecast_t101",
    content = "<color=#EABB5C><size=20>L\225\187\145i Ch\198\161i</size></color>\n1, c\198\176\225\187\157ng h\195\179a Trang B\225\187\139 ti\195\170u hao <color=#1ADD1F>\196\144\195\161 Ch\195\186c Ph\195\186c</color>, Trang B\225\187\139 cao c\225\186\165p s\225\186\189 ti\195\170u hao th\195\170m <color=#1ADD1F>\196\144\195\161 Linh H\225\187\147n</color> v\195\160 <color=#1ADD1F>\196\144\195\161 Maya</color>.\n2, C\225\186\165p c\198\176\225\187\157ng h\195\179a t\196\131ng l\195\170n, hi\225\187\135u \225\187\169ng <color=#1ADD1F>\195\129nh S\195\161ng</color> Ngo\225\186\161i H\195\172nh Trang B\225\187\139 c\197\169ng s\225\186\189 thay \196\145\225\187\149i.\n3, Khi c\198\176\225\187\157ng h\195\179a th\225\186\165t b\225\186\161i, Trang B\225\187\139 s\225\186\189 b\225\187\139 r\225\187\155t c\225\186\165p."
  },
  Forecast_t6 = {
    id = "Forecast_t6",
    content = "H\225\187\135 th\225\187\145ng Th\225\187\167 H\225\187\153"
  },
  Forecast_t601 = {
    id = "Forecast_t601",
    content = "<color=#EABB5C><size=20>L\225\187\145i Ch\198\161i</size></color>\nTh\225\187\167 H\225\187\153 c\195\179 ch\225\187\169c n\196\131ng sau:\n1, H\225\186\165p Th\225\187\165 DMG: <color=#1ADD1F>Gi\225\186\163m DMG T\225\186\165n C\195\180ng nh\225\186\173n v\195\160o</color>.\n2, Buff DMG: <color=#1ADD1F>T\196\131ng DMG khi t\225\186\165n c\195\180ng</color>.\n3, Gi\225\186\163m C\195\180ng T\225\187\145c Qu\195\161i: <color=#1ADD1F>Gi\225\186\163m C\195\180ng T\225\187\145c c\225\187\167a qu\195\161i</color>.\n4, B\225\186\177ng c\195\161ch ti\195\170u hao <color=#1ADD1F>Tinh Th\225\186\161ch</color> v\195\160 <color=#1ADD1F>V\195\160ng</color> \196\145\225\187\131 t\196\131ng sao c\198\176\225\187\157ng h\195\179a cho Th\225\187\167 H\225\187\153.\n5, K\195\173ch ho\225\186\161t c\198\176\225\187\157ng h\195\179a Th\225\187\167 H\225\187\153 c\195\179 th\225\187\131 nh\225\186\173n th\195\170m thu\225\187\153c t\195\173nh Th\225\187\167 H\225\187\153 t\198\176\198\161ng \225\187\169ng.\n6, <color=#1ADD1F>Th\225\187\167 H\225\187\153 c\195\179 nhi\225\187\129u thu\225\187\153c t\195\173nh c\195\179 th\225\187\131 c\195\179 hi\225\187\135u l\225\187\177c c\195\185ng l\195\186c</color>."
  },
  Forecast_t5 = {
    id = "Forecast_t5",
    content = "H\225\187\135 th\225\187\145ng VIP"
  },
  Forecast_t501 = {
    id = "Forecast_t501",
    content = "<color=#EABB5C><size=20>L\225\187\145i Ch\198\161i</size></color>\n1, VIP l\195\160 ch\225\186\191 \196\145\225\187\153 <color=#1ADD1F>m\225\187\159 kh\195\179a Nhi\225\187\135m V\225\187\165</color>, ho\195\160n th\195\160nh t\225\186\165t c\225\186\163 Nhi\225\187\135m V\225\187\165 trong m\225\187\151i 1 m\225\187\145c VIP c\195\179 th\225\187\131 m\225\187\159 kh\195\179a VIP t\198\176\198\161ng \225\187\169ng, nh\225\186\173n <color=#1ADD1F>Qu\195\160 VIP</color> v\195\160 k\195\173ch ho\225\186\161t <color=#1ADD1F>\196\144\225\186\183c Quy\225\187\129n VIP</color> t\198\176\198\161ng \225\187\169ng, \196\145\225\187\147ng th\225\187\157i m\225\187\159 Nhi\225\187\135m V\225\187\165 c\225\187\167a <color=#1ADD1F>m\225\187\145c VIP k\225\186\191 ti\225\186\191p</color>.\n2, B\225\186\177ng c\195\161ch mua <color=#3CD937>T\196\131ng VIP Ngay</color> c\195\179 th\225\187\131 h\198\176\225\187\159ng ngay ph\195\186c l\225\187\163i \196\145\225\186\183c quy\225\187\129n VIP, tr\195\161nh nh\225\187\175ng r\225\186\175c r\225\187\145i khi l\195\160m Nhi\225\187\135m V\225\187\165."
  },
  Forecast_t502 = {
    id = "Forecast_t502",
    content = "<color=#EABB5C><size=20>\196\144\225\186\183c Quy\225\187\129n VIP</size></color>\n<color=#FFFC00>B\225\186\163n \196\145\225\187\147 ri\195\170ng cho VIP</color>\n<color=#FF8A00>Thu h\225\187\147i T\195\185y Th\195\162n</color>\n<color=#FF8A00>Ti\225\187\135m Ti\225\187\135n L\225\187\163i</color>\n<color=#FF8A00>Kho T\195\185y Th\195\162n</color>\n<color=#FF8A00>Gh\195\169p T\195\185y Th\195\162n</color>\n<color=#FF8A00>T\225\187\177 \196\144\225\187\153ng Thu H\225\187\147i</color>\n<color=#FF8A00>T\225\187\177 Mua Thu\225\187\145c</color>\n<color=#FF8A00>T\225\187\177 \196\144\225\187\153ng Nh\225\186\183t</color>\n<color=#1add1f>Buff EXP</color>\n<color=#1add1f>Buff t\225\187\183 l\225\187\135 r\198\161i</color>\n<color=#1add1f>Buff thu h\225\187\147i v\195\160ng</color>\n<color=#1add1f>Quy\225\187\129n h\225\186\161n l\195\170n k\225\187\135 tr\195\170n S\195\160n Giao D\225\187\139ch</color>"
  },
