  WildBossDescription16 = {
    id = "WildBossDescription16",
    content = "BOSS M\225\187\153c Tinh ng\195\163 xu\225\187\145ng, Y\195\170u C\195\162y Di\195\170m Ma v\195\172 \196\145\225\187\131 s\225\187\159 h\225\187\175u S\225\187\169c M\225\186\161nh L\225\187\173a m\195\160 c\195\162y v\225\187\145n kh\195\180ng th\225\187\131 c\195\179 \196\145\198\176\225\187\163c m\195\160 \196\145\195\163 b\195\161n linh h\225\187\147n c\225\187\167a h\225\187\141 cho \195\161c qu\225\187\183"
