  gameguide_d1_1 = {
    id = "gameguide_d1_1",
    content = "<color=#EABB5C><size=20>\196\144i\225\187\131m V\225\187\139 Th\198\176\225\187\157ng</size></color>\n1. M\225\187\151i b\225\186\163n \196\145\225\187\147 c\195\179 c\195\161c \196\145i\225\187\131m qu\195\161i v\225\187\155i h\225\187\135 s\225\187\145 EXP kh\195\161c nhau, \196\145\225\187\153 kh\195\179 c\195\160ng cao, ti\195\170u di\225\187\135t qu\195\161i v\225\186\173t s\225\186\189 nh\225\186\173n \196\145\198\176\225\187\163c c\195\160ng nhi\225\187\129u EXP. Nh\225\187\175ng \196\145i\225\187\131m qu\195\161i c\195\179 h\225\187\135 s\225\187\145 cao y\195\170u c\225\186\167u ng\198\176\225\187\157i ch\198\161i \196\145\225\186\161t <color=#1add1f>Ph\195\178ng Th\225\187\167</color> t\198\176\198\161ng \225\187\169ng, giai \196\145o\225\186\161n \196\145\225\186\167u c\195\179 th\225\187\131 v\195\160o <color=#1add1f>giao di\225\187\135n r\195\168n Hu\225\187\179nh Th\225\186\161ch</color> ch\225\187\141n <color=#1add1f>\196\144\195\161 Hu\225\187\179nh Quang Th\225\187\167y</color> \196\145\225\187\131 n\195\162ng c\225\186\165p gi\195\186p t\196\131ng Ph\195\178ng Th\225\187\167\n2. V\225\187\155i c\195\185ng l\198\176\225\187\163ng s\195\161t th\198\176\198\161ng, c\225\186\165p \196\145\225\187\153 \196\144i\225\187\131m V\225\187\139 c\195\160ng cao th\195\172 hi\225\187\135u su\225\186\165t c\225\187\167a \196\144i\225\187\131m V\225\187\139 c\195\160ng cao"
  },
  gameguide_d1_2 = {
    id = "gameguide_d1_2",
    content = "<color=#EABB5C><size=20>\196\144i\225\187\131m V\225\187\139 H\225\187\153i Vi\195\170n</size></color>\n1. M\225\187\153t s\225\187\145 \196\144i\225\187\131m V\225\187\139 y\195\170u c\225\186\167u \196\145\225\186\161t c\225\186\165p H\225\187\153i Vi\195\170n nh\225\186\165t \196\145\225\187\139nh m\225\187\155i c\195\179 th\225\187\131 khi\195\170u chi\225\186\191n, t\225\186\161i nh\225\187\175ng \196\145i\225\187\131m qu\195\161i H\225\187\153i Vi\195\170n n\195\160y, <color=#1add1f>t\225\187\137 l\225\187\135 r\198\161i trang b\225\187\139</color> cao h\198\161n, <color=#1add1f>EXP thu \196\145\198\176\225\187\163c</color> c\197\169ng nhi\225\187\129u h\198\161n."
  },
  gameguide_d1_3 = {
    id = "gameguide_d1_3",
    content = "<color=#EABB5C><size=20>Thu\225\187\145c EXP</size></color>\n1. <color=#1add1f>Thu\225\187\145c EXP c\195\179 th\225\187\131 t\196\131ng th\195\170m 30% EXP thu \196\145\198\176\225\187\163c.</color> Ng\198\176\225\187\157i ch\198\161i c\195\179 th\225\187\131<color=#1add1f>mua tr\225\187\177c ti\225\186\191p</color> v\195\160 s\225\187\173 d\225\187\165ng h\225\187\163p l\195\189 Thu\225\187\145c EXP \196\145\225\187\131 t\196\131ng c\225\186\165p t\225\187\145t h\198\161n trong giai \196\145o\225\186\161n \196\145\225\186\167u, \196\145\225\186\169y nhanh t\225\187\145c \196\145\225\187\153 nh\225\186\173n t\195\160i nguy\195\170n."
  },
  gameguide_d1_5 = {
    id = "gameguide_d1_5",
    content = "<color=#EABB5C>Ti\195\170u \196\145\225\187\129 Ki\225\187\131m Tra 5</color>\n1. Di\225\187\135t Qu\195\161i V\195\160ng v\195\160 Th\225\187\167 L\196\169nh c\195\179 t\225\187\137 l\225\187\135 r\198\161i <color=#1add1f>trang b\225\187\139 Tr\195\161c Vi\225\187\135t</color>"
  },
  gameguide_d4 = {
    id = "gameguide_d4",
    content = "<color=#EABB5C>Hi\225\187\135u \225\187\169ng C\198\176\225\187\157ng H\195\179a B\225\187\153 Trang B\225\187\139</color>\nKhi c\225\186\165p c\198\176\225\187\157ng h\195\179a t\196\131ng l\195\170n, b\225\187\153 trang b\225\187\139 s\225\186\189 hi\225\187\131n th\225\187\139 hi\225\187\135u \225\187\169ng \195\161nh s\195\161ng kh\195\161c nhau\n[pic=1]\n<color=#EABB5C><size=20>Gh\195\169p trang b\225\187\139</size></color>\nGh\195\169p trang b\225\187\139: Trang b\225\187\139 ch\195\173nh c\195\179 th\225\187\131 ng\225\186\171u nhi\195\170n k\225\186\191 th\225\187\171a 1 d\195\178ng Tr\195\161c Vi\225\187\135t t\225\187\171 trang b\225\187\139 ph\225\187\165\n[pic=2]"
  },
  gameguide_d5_1 = {
    id = "gameguide_d5_1",
    content = "C\195\179 th\195\170m Qu\195\161i V\195\160ng v\195\160 Th\225\187\167 L\196\169nh, ti\195\170u di\225\187\135t c\195\179 th\225\187\131 nh\225\186\173n <color=#1add1f>l\198\176\225\187\163ng l\225\187\155n EXP</color> v\195\160 th\198\176\225\187\159ng <color=#1add1f>\196\145\225\186\161o c\225\187\165</color>"
  },
  gameguide_d5_2 = {
    id = "gameguide_d5_2",
    content = "Di\225\187\135t H\225\187\143a Long V\198\176\198\161ng xong s\225\186\189 r\198\161i <color=#1add1f>M\225\186\163nh H\225\187\143a Long L\195\162n</color> v\195\160 <color=#1add1f>H\225\187\143a Long T\195\162m</color>, d\195\185ng xong c\195\179 th\225\187\131 nh\225\186\173n <color=#1add1f>l\198\176\225\187\163ng l\225\187\155n EXP</color> v\195\160 <color=#1add1f>V\195\160ng</color>. Sau khi ho\225\186\161t \196\145\225\187\153ng b\225\186\175t \196\145\225\186\167u, H\225\187\143a Long V\198\176\198\161ng c\195\179 th\225\187\131 \196\145\198\176\225\187\163c t\195\172m th\225\186\165y t\225\186\161i b\225\186\163n \196\145\225\187\147 ch\225\187\137 \196\145\225\187\139nh."
  },
  gameguide_d5_3 = {
    id = "gameguide_d5_3",
    content = "C\195\161ch ch\198\161i kinh \196\145i\225\187\131n, c\195\179 th\225\187\131 nh\225\186\173n <color=#1add1f>nhi\225\187\129u EXP</color>, ho\195\160n th\195\160nh ph\195\179 b\225\186\163n c\195\179 t\225\187\183 l\225\187\135 nh\225\186\173n <color=#1add1f>\196\144\195\161</color>"
